create extension if not exists pgcrypto;create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '' check(char_length(display_name)<=60),preferred_unit text not null default 'kg' check(preferred_unit in('kg','lb')),timezone text not null default 'UTC',created_at timestamptz not null default now(),updated_at timestamptz not null default now());create table public.exercises(id uuid primary key default gen_random_uuid(),owner_id uuid references auth.users(id) on delete cascade,name text not null check(char_length(name) between 2 and 100),description text not null default '' check(char_length(description)<=500),muscle_group text not null check(muscle_group in('Chest','Back','Shoulders','Legs','Arms','Core','Full body')),equipment text not null check(equipment in('Barbell','Dumbbell','Cable','Machine','Bodyweight','Kettlebell','Band')),tracking_type text not null check(tracking_type in('weighted','bodyweight','assisted')),archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create table public.workout_sessions(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,workout_date date not null,title text not null check(char_length(title) between 1 and 100),notes text not null default '' check(char_length(notes)<=2000),started_at timestamptz not null default now(),completed_at timestamptz,revision integer not null default 0,last_mutation_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create table public.workout_exercises(id uuid primary key,session_id uuid not null references public.workout_sessions(id) on delete cascade,exercise_id uuid not null references public.exercises(id),position integer not null check(position between 0 and 99),notes text not null default '' check(char_length(notes)<=1000),rest_seconds integer not null default 90 check(rest_seconds between 0 and 3600),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(session_id,position));create table public.exercise_sets(id uuid primary key,workout_exercise_id uuid not null references public.workout_exercises(id) on delete cascade,set_number integer not null check(set_number between 1 and 100),set_type text not null check(set_type in('working','warmup')),weight_kg numeric(12,6) check(weight_kg between 0 and 2000),input_unit text not null check(input_unit in('kg','lb')),reps integer check(reps between 1 and 1000),completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(completed_at is null or reps is not null),unique(workout_exercise_id,set_number));create table public.workout_templates(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(name) between 1 and 100),archived_at timestamptz,revision integer not null default 0,last_mutation_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create table public.template_exercises(id uuid primary key,template_id uuid not null references public.workout_templates(id) on delete cascade,exercise_id uuid not null references public.exercises(id),position integer not null check(position between 0 and 99),target_sets integer not null check(target_sets between 1 and 30),target_reps integer not null check(target_reps between 1 and 1000),rest_seconds integer not null default 90 check(rest_seconds between 0 and 3600),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(template_id,position));create index sessions_user_date on public.workout_sessions(user_id,workout_date desc);create index workout_exercise_history on public.workout_exercises(exercise_id,session_id);create index exercise_set_parent on public.exercise_sets(workout_exercise_id);create index exercise_owner on public.exercises(owner_id);create index template_owner on public.workout_templates(user_id);create index template_exercise_parent on public.template_exercises(template_id);create function public.touch_updated() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now();return new;end$$;create function public.validate_timezone() returns trigger language plpgsql set search_path='' as $$begin if not exists(select 1 from pg_timezone_names where name=new.timezone) then raise exception 'Invalid timezone';end if;return new;end$$;create trigger profile_timezone before insert or update on public.profiles for each row execute function public.validate_timezone();create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$declare tz text;begin tz=coalesce(new.raw_user_meta_data->>'timezone','UTC');if not exists(select 1 from pg_timezone_names where name=tz) then tz='UTC';end if;insert into public.profiles(id,display_name,timezone) values(new.id,left(coalesce(new.raw_user_meta_data->>'display_name',''),60),tz);return new;end$$;create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();create function public.validate_set_load() returns trigger language plpgsql set search_path='' as $$declare kind text;begin select e.tracking_type into kind from public.exercises e join public.workout_exercises we on we.exercise_id=e.id where we.id=new.workout_exercise_id;if kind is null then raise exception 'Exercise unavailable';end if;if kind='bodyweight' and new.weight_kg is not null then raise exception 'Bodyweight sets cannot have weight';end if;if kind<>'bodyweight' and new.completed_at is not null and new.weight_kg is null then raise exception 'Completed sets need a weight';end if;return new;end$$;create trigger validate_set before insert or update on public.exercise_sets for each row execute function public.validate_set_load();create function public.protect_exercise_type() returns trigger language plpgsql set search_path='' as $$begin if new.tracking_type<>old.tracking_type then raise exception 'Tracking type cannot change;create another exercise';end if;if new.owner_id is distinct from old.owner_id then raise exception 'Exercise owner cannot change';end if;return new;end$$;create trigger protect_type before update on public.exercises for each row execute function public.protect_exercise_type();alter table public.profiles enable row level security;create trigger touch_profiles before update on public.profiles for each row execute function public.touch_updated();grant select,insert,update,delete on public.profiles to authenticated;alter table public.exercises enable row level security;create trigger touch_exercises before update on public.exercises for each row execute function public.touch_updated();grant select,insert,update,delete on public.exercises to authenticated;alter table public.workout_sessions enable row level security;create trigger touch_workout_sessions before update on public.workout_sessions for each row execute function public.touch_updated();grant select,insert,update,delete on public.workout_sessions to authenticated;alter table public.workout_exercises enable row level security;create trigger touch_workout_exercises before update on public.workout_exercises for each row execute function public.touch_updated();grant select,insert,update,delete on public.workout_exercises to authenticated;alter table public.exercise_sets enable row level security;create trigger touch_exercise_sets before update on public.exercise_sets for each row execute function public.touch_updated();grant select,insert,update,delete on public.exercise_sets to authenticated;alter table public.workout_templates enable row level security;create trigger touch_workout_templates before update on public.workout_templates for each row execute function public.touch_updated();grant select,insert,update,delete on public.workout_templates to authenticated;alter table public.template_exercises enable row level security;create trigger touch_template_exercises before update on public.template_exercises for each row execute function public.touch_updated();grant select,insert,update,delete on public.template_exercises to authenticated;create policy profiles_read on public.profiles for select to authenticated using(id=(select auth.uid()));create policy profiles_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));create policy exercises_read on public.exercises for select to authenticated using(owner_id is null or owner_id=(select auth.uid()));create policy exercises_insert on public.exercises for insert to authenticated with check(owner_id=(select auth.uid()));create policy exercises_update on public.exercises for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));create policy sessions_owner on public.workout_sessions for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy templates_owner on public.workout_templates for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy workout_exercises_owner on public.workout_exercises for all to authenticated using(exists(select 1 from public.workout_sessions w where w.id=session_id and w.user_id=(select auth.uid()))) with check(exists(select 1 from public.workout_sessions w where w.id=session_id and w.user_id=(select auth.uid())) and exists(select 1 from public.exercises e where e.id=exercise_id and(e.owner_id is null or e.owner_id=(select auth.uid()))));create policy sets_owner on public.exercise_sets for all to authenticated using(exists(select 1 from public.workout_exercises e join public.workout_sessions w on w.id=e.session_id where e.id=workout_exercise_id and w.user_id=(select auth.uid()))) with check(exists(select 1 from public.workout_exercises e join public.workout_sessions w on w.id=e.session_id where e.id=workout_exercise_id and w.user_id=(select auth.uid())));create policy template_exercises_owner on public.template_exercises for all to authenticated using(exists(select 1 from public.workout_templates t where t.id=template_id and t.user_id=(select auth.uid()))) with check(exists(select 1 from public.workout_templates t where t.id=template_id and t.user_id=(select auth.uid())) and exists(select 1 from public.exercises e where e.id=exercise_id and(e.owner_id is null or e.owner_id=(select auth.uid()))));create function public.save_workout(payload jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$declare w public.workout_sessions;item jsonb;s jsonb;kind text;begin if auth.uid() is null then raise exception 'Authentication required';end if;if payload->>'mutation_id' is null or payload->>'revision' is null or (payload->>'revision')::integer<0 then raise exception 'Mutation ID and revision required';end if;if jsonb_array_length(payload->'workout_exercises')>50 then raise exception 'Too many exercises';end if;insert into public.workout_sessions(id,user_id,workout_date,title,started_at) values((payload->>'id')::uuid,auth.uid(),(payload->>'workout_date')::date,payload->>'title',(payload->>'started_at')::timestamptz) on conflict(id) do nothing;select * into w from public.workout_sessions where id=(payload->>'id')::uuid for update;if w.id is null then raise exception 'Workout unavailable';end if;if w.last_mutation_id=(payload->>'mutation_id')::uuid then return jsonb_build_object('revision',w.revision);end if;if w.revision<>(payload->>'revision')::integer then raise exception 'VERSION_CONFLICT';end if;if payload->>'completed_at' is not null and not exists(select 1 from jsonb_array_elements(payload->'workout_exercises') e cross join lateral jsonb_array_elements(e->'exercise_sets') candidate where candidate->>'completed_at' is not null) then raise exception 'Log at least one set before completing a workout';end if;for item in select value from jsonb_array_elements(payload->'workout_exercises') loop if jsonb_array_length(item->'exercise_sets')>100 then raise exception 'Too many sets';end if;if not exists(select 1 from public.exercises e where e.id=(item->>'exercise_id')::uuid and(e.archived_at is null or exists(select 1 from public.workout_exercises we where we.session_id=w.id and we.exercise_id=e.id))) then raise exception 'Exercise unavailable';end if;end loop;delete from public.workout_exercises where session_id=w.id;for item in select value from jsonb_array_elements(payload->'workout_exercises') loop insert into public.workout_exercises(id,session_id,exercise_id,position,notes,rest_seconds) values((item->>'id')::uuid,w.id,(item->>'exercise_id')::uuid,(item->>'position')::integer,coalesce(item->>'notes',''),coalesce((item->>'rest_seconds')::integer,90));for s in select value from jsonb_array_elements(item->'exercise_sets') loop insert into public.exercise_sets(id,workout_exercise_id,set_number,set_type,weight_kg,input_unit,reps,completed_at) values((s->>'id')::uuid,(item->>'id')::uuid,(s->>'set_number')::integer,s->>'set_type',(s->>'weight_kg')::numeric,s->>'input_unit',(s->>'reps')::integer,(s->>'completed_at')::timestamptz);end loop;end loop;update public.workout_sessions set workout_date=(payload->>'workout_date')::date,title=payload->>'title',notes=coalesce(payload->>'notes',''),started_at=(payload->>'started_at')::timestamptz,completed_at=(payload->>'completed_at')::timestamptz,revision=revision+1,last_mutation_id=(payload->>'mutation_id')::uuid where id=w.id returning * into w;return jsonb_build_object('revision',w.revision);end$$;create function public.save_template(payload jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$declare t public.workout_templates;item jsonb;begin if auth.uid() is null then raise exception 'Authentication required';end if;if payload->>'mutation_id' is null or payload->>'revision' is null or (payload->>'revision')::integer<0 then raise exception 'Mutation ID and revision required';end if;if jsonb_array_length(payload->'template_exercises') not between 1 and 50 then raise exception 'Choose between 1 and 50 exercises';end if;insert into public.workout_templates(id,user_id,name) values((payload->>'id')::uuid,auth.uid(),payload->>'name') on conflict(id) do nothing;select * into t from public.workout_templates where id=(payload->>'id')::uuid and archived_at is null for update;if t.id is null then raise exception 'Routine unavailable';end if;if t.last_mutation_id=(payload->>'mutation_id')::uuid then return jsonb_build_object('revision',t.revision);end if;if t.revision<>(payload->>'revision')::integer then raise exception 'VERSION_CONFLICT';end if;for item in select value from jsonb_array_elements(payload->'template_exercises') loop if not exists(select 1 from public.exercises e where e.id=(item->>'exercise_id')::uuid and e.archived_at is null) then raise exception 'Exercise unavailable';end if;end loop;delete from public.template_exercises where template_id=t.id;for item in select value from jsonb_array_elements(payload->'template_exercises') loop insert into public.template_exercises(id,template_id,exercise_id,position,target_sets,target_reps,rest_seconds) values((item->>'id')::uuid,t.id,(item->>'exercise_id')::uuid,(item->>'position')::integer,(item->>'target_sets')::integer,(item->>'target_reps')::integer,(item->>'rest_seconds')::integer);end loop;update public.workout_templates set name=payload->>'name',revision=revision+1,last_mutation_id=(payload->>'mutation_id')::uuid where id=t.id returning * into t;return jsonb_build_object('revision',t.revision);end$$;create function public.history_points(target uuid,since date default null) returns table(id uuid,date date,title text,started_at timestamptz,weight numeric,volume numeric,reps integer,assistance jsonb) language sql stable security invoker set search_path='' as $$ with valid as(select w.id,w.workout_date,w.title,w.started_at,e.tracking_type,s.weight_kg,s.reps from public.workout_sessions w join public.workout_exercises we on we.session_id=w.id join public.exercises e on e.id=we.exercise_id join public.exercise_sets s on s.workout_exercise_id=we.id where e.id=target and w.user_id=auth.uid() and s.completed_at is not null and s.set_type='working' and(since is null or w.workout_date>=since)),a as(select v.id,jsonb_object_agg(v.reps::text,v.load) as values from(select valid.id,valid.reps,min(weight_kg) as load from valid where tracking_type='assisted' group by valid.id,valid.reps)v group by v.id) select v.id,v.workout_date,v.title,v.started_at,max(v.weight_kg) filter(where v.tracking_type='weighted'),sum(v.weight_kg*v.reps) filter(where v.tracking_type='weighted'),max(v.reps),coalesce(a.values,'{}'::jsonb) from valid v left join a on a.id=v.id group by v.id,v.workout_date,v.title,v.started_at,a.values order by v.workout_date,v.started_at,v.id;$$;revoke execute on function public.save_workout(jsonb),public.save_template(jsonb),public.history_points(uuid,date),public.handle_new_user(),public.touch_updated(),public.validate_set_load(),public.protect_exercise_type(),public.validate_timezone() from public,anon;grant execute on function public.save_workout(jsonb),public.save_template(jsonb),public.history_points(uuid,date) to authenticated;